import{_ as t,o as d,c as o,a0 as a}from"./chunks/framework.BQvjZmTX.js";const f=JSON.parse('{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/env-vars.md","filePath":"reference/env-vars.md"}'),r={name:"reference/env-vars.md"};function c(n,e,i,s,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h1><p>Process env vars arca itself reads. (The vars in <code>[secrets]</code> are yours — this is arca&#39;s own surface; <code>arca manifest</code> reports the same table.)</p><table tabindex="0"><thead><tr><th>var</th><th>default</th><th>used for</th></tr></thead><tbody><tr><td><code>ARCA_CONFIG</code></td><td>—</td><td>config file override, between <code>--config</code> and <code>./arca.toml</code> in the search order</td></tr><tr><td><code>ARCA_ENV</code></td><td><code>dev</code></td><td>env context — resolution + routing (<code>--env</code> wins)</td></tr><tr><td><code>ARCA_ACTOR</code></td><td><code>$USER</code> → <code>anon</code></td><td>audit attribution (<code>--actor</code> wins). Self-claimed</td></tr><tr><td><code>ARCA_IDENTITY_FILE</code></td><td><code>~/.config/arca/identity.txt</code></td><td>age identity keyfile for every vault impl</td></tr><tr><td><code>ARCA_CF_TOKEN</code></td><td>—</td><td>bearer token for <code>kind = &quot;cf&quot;</code> vaults — <em>default</em> name; <code>[vaults.*].token_env</code> picks another</td></tr><tr><td><code>CLOUDFLARE_API_TOKEN</code></td><td>—</td><td>API token for <code>cf-secrets-store</code> deploy sinks — <em>default</em> name; <code>[deploy.*].token_env</code> picks another</td></tr></tbody></table><p>Honored XDG paths (when the matching override is unset):</p><table tabindex="0"><thead><tr><th>var</th><th>falls back to</th></tr></thead><tbody><tr><td><code>XDG_CONFIG_HOME</code></td><td><code>~/.config</code> — identity + user-level <code>arca.toml</code></td></tr><tr><td><code>XDG_DATA_HOME</code></td><td><code>~/.local/share</code> — the default <code>vault.age</code></td></tr></tbody></table><p>Two rules of thumb:</p><ul><li><code>token_env</code> config fields name env vars — the token <em>value</em> only ever lives in the process env.</li><li><code>ARCA_ACTOR</code> is a self-claimed string for the audit trail, not authentication; see the <a href="./../explanation/threat-model.html">threat model</a>.</li></ul>',7)])])}const _=t(r,[["render",c]]);export{f as __pageData,_ as default};
